int fd = open("file.dat", O_RDWR);
struct stat st;
fstat(fd, &st);
size_t length = st.st_size;

// Map the file into memory
void* map_start = mmap(NULL,
                       length,
                       PROT_READ | PROT_WRITE,
                       MAP_SHARED, // Changes reflected in the file
                       fd,
                       0);

if (map_start == MAP_FAILED) { /* error handling */ }

char* data = (char*)map_start;
data[0] = 'X'; // Direct manipulation of file content

// Optionally force immediate write back
msync(map_start, length, MS_SYNC);

munmap(map_start, length);
close(fd);
